    \foreach \i in {0,1,2,3} {
      \foreach \j in {0,1,2,3} {
        \fill (0.5*\j, -0.5*\i) circle (2pt);
      }
    }
    \node[anchor=north] at (0.75,-2.3) {square};
  \end{scope}
